34:   function ensureAudio() {
35:     if (!audioContext) {
36:       const Context = window.AudioContext || window.webkitAudioContext;
37:       if (!Context) throw new Error('Este navegador no tiene Web Audio API.');
38:       audioContext = new Context({ latencyHint: 'interactive' });
39:       for (const id of ['a', 'b']) createDeck(id);
