169:   function startDemo(id) {
170:     const bpm = id === 'a' ? 120 : 124;
171:     const name = id === 'a' ? 'Neon pulse · 01' : 'Afterglow · 02';
172:     const blob = makeDemoWav(bpm, id === 'a' ? 17 : 29);
173:     attachTrack(id, URL.createObjectURL(blob), { name, artist: 'DJ Lab · demo generativa', bpm, duration: 60 / bpm * 16, demo: true, loop: true });
174:     playDeck(id);
175:     toast(`Demo ${id.toUpperCase()} lista · ${bpm} BPM`);
176:   }
