178:   async function playDeck(id) {
179:     try {
180:       ensureAudio();
181:       const deck = decks[id];
182:       if (!deck.audio.src) { toast('Carga una pista o inicia la demo primero.'); return; }
183:       if (deck.audio.paused) await deck.audio.play(); else deck.audio.pause();
184:       updateTransport(id);
185:       setStatus(deck.audio.paused ? 'AUDIO PREPARADO' : 'REPRODUCIENDO');
186:       updatePhase();
187:     } catch (error) {
188:       toast(error.message || 'No se pudo iniciar el audio.');
189:     }
190:   }
