192:   function updateTransport(id) {
193:     const button = $(`.play-button[data-deck="${id}"]`);
194:     if (!button) return;
195:     const playing = Boolean(decks[id]?.audio && !decks[id].audio.paused);
196:     button.textContent = playing ? 'Ⅱ' : '▶';
197:     button.classList.toggle('is-playing', playing);
198:     button.setAttribute('aria-label', `${playing ? 'Pausar' : 'Reproducir'} Deck ${id.toUpperCase()}`);
199:   }
