201:   function syncDeck(id) {
202:     ensureAudio();
203:     const deck = decks[id];
204:     const target = id === 'a' ? decks.b.bpm : decks.a.bpm;
205:     deck.pitch = Math.max(-8, Math.min(8, (target / deck.baseBpm - 1) * 100));
206:     $(`[data-pitch="${id}"]`).value = deck.pitch;
207:     setPitch(id, deck.pitch);
208:     if (decks.a.audio.src && decks.b.audio.src) {
209:       const master = decks.a.audio.currentTime || 0;
210:       deck.audio.currentTime = master;
211:     }
212:     toast(`Deck ${id.toUpperCase()} sincronizado a ${target.toFixed(1)} BPM`);
213:   }
