223:   function formatTime(seconds) {
224:     if (!Number.isFinite(seconds)) return '00:00';
225:     const mins = Math.floor(seconds / 60).toString().padStart(2, '0');
226:     const secs = Math.floor(seconds % 60).toString().padStart(2, '0');
227:     return `${mins}:${secs}`;
228:   }
229: 
230:   function renderWave(id) {
231:     const deck = decks[id];
232:     const canvas = $(`#wave-${id}`);
233:     const ctx = canvas.getContext('2d');
234:     const width = canvas.clientWidth || 500;
235:     const height = canvas.clientHeight || 67;
236:     const ratio = Math.min(window.devicePixelRatio || 1, 2);
237:     if (canvas.width !== Math.floor(width * ratio) || canvas.height !== Math.floor(height * ratio)) {
238:       canvas.width = Math.floor(width * ratio); canvas.height = Math.floor(height * ratio);
239:     }
240:     ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
241:     ctx.clearRect(0, 0, width, height);
242:     ctx.fillStyle = '#0c1016'; ctx.fillRect(0, 0, width, height);
243:     ctx.strokeStyle = '#202630'; ctx.lineWidth = 1;
244:     ctx.beginPath(); ctx.moveTo(0, height / 2); ctx.lineTo(width, height / 2); ctx.stroke();
245:     const colors = ['#fa596d', '#72e294', '#57aef4'];
246:     const bands = [[0, 250], [250, 4000], [4000, 12000]];
247:     const sampleRate = audioContext?.sampleRate || 44100;
248:     const bins = deck.data.length;
249:     const maxHz = sampleRate / 2;
250:     const active = Boolean(deck.analyser && !deck.audio.paused && deck.audio.src);
251:     if (active) deck.analyser.getByteFrequencyData(deck.data);
252:     const columns = Math.max(1, Math.floor(width / 3));
253:     const offset = deck.audio.currentTime ? Math.floor(deck.audio.currentTime * 14) % columns : 0;
254:     for (let x = 0; x < columns; x++) {
255:       const pos = (x + offset) % columns;
256:       let total = 0;
257:       for (let band = 0; band < bands.length; band++) {
258:         const [lo, hi] = bands[band];
259:         const start = Math.max(0, Math.floor(lo / maxHz * bins));
260:         const end = Math.max(start + 1, Math.min(bins, Math.floor(hi / maxHz * bins)));
261:         let energy = 0;
262:         if (active) {
263:           for (let i = start; i < end; i++) energy += deck.data[i];
264:           energy /= (end - start) * 255;
265:         } else {
266:           const wave = Math.sin((pos * 0.083) + band * 1.7 + (id === 'b' ? 0.8 : 0));
267:           energy = deck.audio.src ? 0.12 + Math.abs(wave) * 0.2 : 0.035;
268:         }
269:         const barHeight = Math.max(2, energy * height * 0.75);
270:         const alpha = active ? 0.42 + Math.min(0.55, energy) : 0.20;
271:         ctx.globalAlpha = alpha;
272:         ctx.fillStyle = colors[band];
273:         const yOffset = band === 0 ? -1 : band === 1 ? 0 : 1;
274:         ctx.fillRect(pos * 3, (height - barHeight) / 2 + yOffset * 5, 2, barHeight);
275:         total += energy;
276:       }
277:       if (active && total > 0.14) {
278:         ctx.globalAlpha = 0.25;
279:         ctx.fillStyle = id === 'a' ? '#54e3dc' : '#ff4e97';
280:         ctx.fillRect(pos * 3, 0, 1, height);
281:       }
282:     }
283:     ctx.globalAlpha = 1;
284:     const progress = deck.audio.duration ? deck.audio.currentTime / deck.audio.duration : 0;
285:     const playX = progress * width;
286:     ctx.fillStyle = id === 'a' ? '#dcfff9' : '#ffe0ed';
287:     ctx.shadowColor = id === 'a' ? '#54e3dc' : '#ff4e97'; ctx.shadowBlur = 7;
288:     ctx.fillRect(playX, 0, 1, height); ctx.shadowBlur = 0;
289:     $(`#time-${id}`).textContent = `${formatTime(deck.audio.currentTime || 0)} / ${formatTime(deck.audio.duration)}`;
290:   }
