342:   function renderLibrary() {
343:     const body = $('#library-body');
344:     $('#library-count').textContent = `${library.length} ${library.length === 1 ? 'pista' : 'pistas'}`;
345:     if (!library.length) {
346:       body.innerHTML = '<tr class="empty-row"><td colspan="5"><span>♫</span><strong>Tu biblioteca empieza acá</strong><small>Inicia una demo o carga archivos de audio desde tu dispositivo.</small></td></tr>';
347:       return;
348:     }
349:     body.replaceChildren(...library.slice(0, 20).map(track => {
350:       const row = document.createElement('tr');
351:       const name = document.createElement('td'); name.innerHTML = `<div class="library-track"><i>♪</i><span><b></b><small></small></span></div>`;
352:       name.querySelector('b').textContent = track.name; name.querySelector('small').textContent = track.artist || track.source;
353:       const duration = document.createElement('td'); duration.textContent = formatTime(track.duration || 0);
354:       const bpm = document.createElement('td'); bpm.textContent = track.bpm ? Number(track.bpm).toFixed(1) : '—';
355:       const source = document.createElement('td'); source.textContent = track.source || 'Local';
356:       const action = document.createElement('td');
357:       const loadA = document.createElement('button'); loadA.className = 'table-load'; loadA.textContent = 'A'; loadA.title = 'Cargar en Deck A';
358:       const loadB = document.createElement('button'); loadB.className = 'table-load'; loadB.textContent = 'B'; loadB.title = 'Cargar en Deck B';
359:       loadA.addEventListener('click', () => loadLibraryTrack(track, 'a')); loadB.addEventListener('click', () => loadLibraryTrack(track, 'b'));
360:       action.append(loadA, document.createTextNode(' '), loadB); row.append(name, duration, bpm, source, action); return row;
361:     }));
362:   }
