127:   function makeDemoWav(bpm, seed) {
128:     const sampleRate = 22050;
129:     const beat = 60 / bpm;
130:     const beatCount = 16;
131:     const length = Math.ceil(sampleRate * beat * beatCount);
132:     const samples = new Float32Array(length);
133:     let state = seed >>> 0;
134:     const random = () => { state = (state * 1664525 + 1013904223) >>> 0; return state / 4294967296; };
135:     for (let b = 0; b < beatCount; b++) {
136:       const start = Math.floor(b * beat * sampleRate);
137:       const kickLength = Math.floor(sampleRate * 0.24);
138:       for (let i = 0; i < kickLength && start + i < length; i++) {
139:         const t = i / sampleRate;
140:         const env = Math.exp(-t * 17);
141:         const freq = 43 + 75 * Math.exp(-t * 28);
142:         samples[start + i] += Math.sin(2 * Math.PI * freq * t) * env * 0.78;
143:       }
144:       if (b % 4 === 1 || b % 4 === 3) {
145:         const clapStart = start + Math.floor(sampleRate * beat * 0.12);
146:         for (let i = 0; i < sampleRate * 0.15 && clapStart + i < length; i++) {
147:           const t = i / sampleRate;
148:           samples[clapStart + i] += (random() * 2 - 1) * Math.exp(-t * 24) * 0.17;
149:         }
150:       }
151:       const hatStart = start + Math.floor(sampleRate * beat * 0.5);
152:       for (let i = 0; i < sampleRate * 0.045 && hatStart + i < length; i++) {
153:         const t = i / sampleRate;
154:         samples[hatStart + i] += (random() * 2 - 1) * Math.exp(-t * 75) * 0.08;
155:       }
156:     }
157:     const buffer = new ArrayBuffer(44 + samples.length * 2);
158:     const view = new DataView(buffer);
159:     const write = (offset, text) => [...text].forEach((char, index) => view.setUint8(offset + index, char.charCodeAt(0)));
160:     write(0, 'RIFF'); view.setUint32(4, 36 + samples.length * 2, true); write(8, 'WAVE');
161:     write(12, 'fmt '); view.setUint32(16, 16, true); view.setUint16(20, 1, true);
162:     view.setUint16(22, 1, true); view.setUint32(24, sampleRate, true); view.setUint32(28, sampleRate * 2, true);
163:     view.setUint16(32, 2, true); view.setUint16(34, 16, true); write(36, 'data');
164:     view.setUint32(40, samples.length * 2, true);
165:     for (let i = 0; i < samples.length; i++) view.setInt16(44 + i * 2, Math.max(-1, Math.min(1, samples[i])) * 32767, true);
166:     return new Blob([buffer], { type: 'audio/wav' });
167:   }
