304:   function checkMix() {
305:     ensureAudio();
306:     const a = decks.a, b = decks.b;
307:     const card = $('#score-card');
308:     if (!a.audio.src || !b.audio.src) {
309:       card.className = 'score-card bad'; $('#score-title').textContent = 'FALTAN PISTAS';
310:       $('#score-message').textContent = 'Carga o inicia las demos en ambos decks.'; $('#score-value').textContent = '—'; return;
311:     }
312:     const bpmDifference = Math.abs(b.bpm - TARGET_BPM);
313:     if (!a.audio.paused && !b.audio.paused) {
314:       const phaseA = ((a.audio.currentTime * a.bpm / 60) % 1 + 1) % 1;
315:       const phaseB = ((b.audio.currentTime * b.bpm / 60) % 1 + 1) % 1;
316:       let diff = Math.abs(phaseA - phaseB) * 60000 / TARGET_BPM;
317:       diff = Math.min(diff, 60000 / TARGET_BPM - diff);
318:       const result = diff < 30 ? 'PERFECT' : diff < 70 ? 'GOOD' : 'DESINCRONIZADO';
319:       card.className = `score-card ${result === 'PERFECT' ? 'good' : result === 'GOOD' ? '' : 'bad'}`;
320:       $('#score-title').textContent = result === 'DESINCRONIZADO' ? result : `${result} · BEATMATCH`;
321:       $('#score-message').textContent = result === 'PERFECT' ? 'Fase alineada. ¡Mezcla limpia!' : result === 'GOOD' ? 'Muy cerca. Ajusta el jog imaginario.' : 'Desfase detectado. Pulsa SYNC y prueba otra vez.';
322:       $('#score-value').textContent = `${Math.round(diff)} ms`;
323:       $('#phase-readout').textContent = `FASE ${Math.round(diff)} MS`;
324:     } else if (bpmDifference <= 0.5) {
