330:       $('#score-message').textContent = `Lleva el Deck B de ${b.bpm.toFixed(1)} a ${TARGET_BPM} BPM.`;
331:       $('#score-value').textContent = `${(b.bpm - TARGET_BPM > 0 ? '+' : '')}${(b.bpm - TARGET_BPM).toFixed(1)}`;
332:     }
