541:   function handleMidi(event) {
542:     const [status, data1, data2] = event.data;
543:     const command = status & 0xf0;
544:     const channel = status & 0x0f;
545:     if ((command === 0x90 || command === 0x80) && data2 > 0) {
546:       // Standard channel-1 notes: 60 toggles Deck A, 61 toggles Deck B.
547:       if (channel === 0 && data1 === 60) playDeck('a');
548:       if (channel === 0 && data1 === 61) playDeck('b');
549:       return;
550:     }
551:     if (command === 0xb0) {
552:       if (data1 === 7) { $('[data-volume="a"]').value = Math.round(data2 / 127 * 100); setVolume('a', data2 / 127); }
553:       if (data1 === 8) { $('[data-volume="b"]').value = Math.round(data2 / 127 * 100); setVolume('b', data2 / 127); }
554:       if (data1 === 9) setCrossfader(Math.round(data2 / 127 * 100));
555:     }
556:   }
