286:       if (deck.objectUrl !== url) return;
287:       const OfflineContext = window.OfflineAudioContext || window.webkitOfflineAudioContext;
288:       if (!OfflineContext) return;
289:       const context = new OfflineContext(1, 1, 11025);
290:       const decoded = await context.decodeAudioData(audioBuffer);
291:       const samples = decoded.getChannelData(0);
292:       const sampleRate = decoded.sampleRate;
293:       const hop = 256;
294:       const energies = [];
295:       for (let start = 0; start + 1024 < samples.length; start += hop) {
296:         let energy = 0;
297:         for (let i = 0; i < 1024; i++) energy += samples[start + i] ** 2;
298:         energies.push(Math.sqrt(energy / 1024));
299:       }
300:       if (deck.objectUrl !== url || energies.length < 20) return;
301:       const mean = energies.reduce((sum, value) => sum + value, 0) / energies.length;
302:       const peaks = [];
303:       for (let i = 1; i < energies.length - 1; i++) {
304:         if (energies[i] > mean * 1.45 && energies[i] >= energies[i - 1] && energies[i] > energies[i + 1] && i - (peaks.at(-1)?.index || -Infinity) > Math.floor(sampleRate * 0.22 / hop)) peaks.push({ index: i, time: i * hop / sampleRate });
