306:       const intervals = peaks.slice(1).map((peak, i) => peak.time - peaks[i].time).filter(value => value > 0.28 && value < 1.5).sort((a, b) => a - b);
307:       if (intervals.length < 3) return;
308:       let bpm = 60 / intervals[Math.floor(intervals.length / 2)];
309:       if (bpm < 70) bpm *= 2; else if (bpm > 160) bpm /= 2;
310:       if (bpm >= 70 && bpm <= 160) {
311:         deck.estimatedBpm = bpm;
312:         deck.baseBpm = bpm;
