285:   function analyzeFrequencyBands(id, sampleRate) {
286:     const deck = decks[id];
287:     const bins = deck.data.length;
288:     const maxHz = sampleRate / 2;
289:     const ranges = { low: [40, 250], mid: [250, Math.min(4000, maxHz)], high: [Math.min(4000, maxHz - 1), maxHz] };
290:     for (const [name, [lo, hi]] of Object.entries(ranges)) {
291:       const start = Math.max(0, Math.floor(lo / maxHz * bins));
292:       const end = Math.max(start + 1, Math.min(bins, Math.floor(hi / maxHz * bins)));
293:       let energy = 0;
294:       for (let i = start; i < end; i++) energy += deck.data[i] / 255;
295:       deck.bandLevels[name] = energy / (end - start);
296:       $(`#band-${name}-${id}`).textContent = `${Math.round(deck.bandLevels[name] * 100)}%`;
297:     }
298:     if (deck.audio.currentTime > 0.08 && deck.audio.currentTime < (deck.audio.duration || Infinity) - 0.08) {
299:       const lowEnergy = deck.bandLevels.low;
300:       deck.bpmSamples.push({ time: deck.audio.currentTime, energy: lowEnergy });
301:       const cutoff = deck.audio.currentTime - 12;
302:       while (deck.bpmSamples.length && deck.bpmSamples[0].time < cutoff) deck.bpmSamples.shift();
303:       estimateBpmFromEnergy(id);
304:     }
305:   }
