307:   async function analyzeOfflineBpm(id) {
308:     const deck = decks[id];
309:     const url = deck.objectUrl;
310:     if (!url || url.startsWith('https://') || !window.AudioContext && !window.webkitAudioContext) return;
311:     try {
312:       const response = await fetch(url);
313:       if (!response.ok) return;
314:       const audioBuffer = await response.arrayBuffer();
315:       if (deck.objectUrl !== url) return;
316:       const OfflineContext = window.OfflineAudioContext || window.webkitOfflineAudioContext;
317:       if (!OfflineContext) return;
318:       const context = new OfflineContext(1, 1, 11025);
319:       const decoded = await context.decodeAudioData(audioBuffer);
320:       const samples = decoded.getChannelData(0);
321:       const sampleRate = decoded.sampleRate;
322:       const hop = 256;
323:       const energies = [];
324:       for (let start = 0; start + 1024 < samples.length; start += hop) {
325:         let energy = 0;
326:         for (let i = 0; i < 1024; i++) energy += samples[start + i] ** 2;
327:         energies.push(Math.sqrt(energy / 1024));
328:       }
329:       if (deck.objectUrl !== url || energies.length < 20) return;
330:       const mean = energies.reduce((sum, value) => sum + value, 0) / energies.length;
331:       const peaks = [];
332:       for (let i = 1; i < energies.length - 1; i++) {
333:         if (energies[i] > mean * 1.45 && energies[i] >= energies[i - 1] && energies[i] > energies[i + 1] && i - (peaks.at(-1)?.index || -Infinity) > Math.floor(sampleRate * 0.22 / hop)) peaks.push({ index: i, time: i * hop / sampleRate });
334:       }
335:       const intervals = peaks.slice(1).map((peak, i) => peak.time - peaks[i].time).filter(value => value > 0.28 && value < 1.5).sort((a, b) => a - b);
336:       if (intervals.length < 3) return;
337:       let bpm = 60 / intervals[Math.floor(intervals.length / 2)];
338:       if (bpm < 70) bpm *= 2; else if (bpm > 160) bpm /= 2;
339:       if (bpm >= 70 && bpm <= 160) {
340:         deck.estimatedBpm = bpm;
341:         deck.baseBpm = bpm;
342:         setPitch(id, deck.pitch);
343:         $(`#analysis-status-${id}`).textContent = `LOCAL · ≈${bpm.toFixed(1)} BPM`;
344:         const entry = library.find(track => track.name === deck.trackName && track.source === 'Local');
345:         if (entry) { entry.bpm = bpm; persistLibrary(); renderLibrary(); }
346:       }
347:     } catch { $(`#analysis-status-${id}`).textContent = 'LOCAL · BPM NO DISPONIBLE'; }
348:   }
