350:   function estimateBpmFromEnergy(id) {
351:     const deck = decks[id];
352:     const samples = deck.bpmSamples;
353:     if (samples.length < 36) return;
354:     const mean = samples.reduce((sum, sample) => sum + sample.energy, 0) / samples.length;
355:     const variance = samples.reduce((sum, sample) => sum + (sample.energy - mean) ** 2, 0) / samples.length;
356:     if (variance < 0.00002) return;
357:     const threshold = mean + Math.sqrt(variance) * 0.7;
358:     const peaks = [];
359:     for (let i = 1; i < samples.length - 1; i++) {
360:       if (samples[i].energy > threshold && samples[i].energy >= samples[i - 1].energy && samples[i].energy > samples[i + 1].energy && samples[i].time - (peaks.at(-1)?.time || -Infinity) > 0.22) peaks.push(samples[i]);
361:     }
362:     if (peaks.length < 5) return;
363:     const intervals = peaks.slice(1).map((peak, i) => peak.time - peaks[i].time).filter(interval => interval > 0.28 && interval < 1.5).sort((a, b) => a - b);
364:     if (intervals.length < 4) return;
365:     const interval = intervals[Math.floor(intervals.length / 2)];
366:     const bpm = 60 / interval;
367:     const normalized = bpm < 70 ? bpm * 2 : bpm > 160 ? bpm / 2 : bpm;
368:     if (normalized >= 70 && normalized <= 160) {
369:       deck.estimatedBpm = normalized;
370:       $(`#analysis-status-${id}`).textContent = `LOCAL · ≈${normalized.toFixed(1)} BPM`;
371:     }
372:   }
