374:   function renderWave(id) {
375:     const deck = decks[id];
376:     const canvas = $(`#wave-${id}`);
377:     const ctx = canvas.getContext('2d');
378:     const width = canvas.clientWidth || 500;
379:     const height = canvas.clientHeight || 67;
380:     const ratio = Math.min(window.devicePixelRatio || 1, 2);
381:     if (canvas.width !== Math.floor(width * ratio) || canvas.height !== Math.floor(height * ratio)) {
382:       canvas.width = Math.floor(width * ratio); canvas.height = Math.floor(height * ratio);
383:     }
384:     ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
385:     ctx.clearRect(0, 0, width, height);
386:     ctx.fillStyle = '#0c1016'; ctx.fillRect(0, 0, width, height);
387:     ctx.strokeStyle = '#202630'; ctx.lineWidth = 1;
388:     ctx.beginPath(); ctx.moveTo(0, height / 2); ctx.lineTo(width, height / 2); ctx.stroke();
389:     const colors = ['#fa596d', '#72e294', '#57aef4'];
390:     const bands = [[0, 250], [250, 4000], [4000, 12000]];
391:     const sampleRate = audioContext?.sampleRate || 44100;
392:     const bins = deck.data.length;
393:     const maxHz = sampleRate / 2;
394:     const active = Boolean(deck.analyser && !deck.audio.paused && deck.audio.src && !deck.audio.src.startsWith('https://www.youtube'));
395:     if (active) {
396:       deck.analyser.getByteFrequencyData(deck.data);
397:       analyzeFrequencyBands(id, sampleRate);
398:     }
399:     const columns = Math.max(1, Math.floor(width / 3));
400:     const offset = deck.audio.currentTime ? Math.floor(deck.audio.currentTime * 14) % columns : 0;
401:     for (let x = 0; x < columns; x++) {
402:       const pos = (x + offset) % columns;
403:       let total = 0;
404:       for (let band = 0; band < bands.length; band++) {
405:         const [lo, hi] = bands[band];
406:         const start = Math.max(0, Math.floor(lo / maxHz * bins));
407:         const end = Math.max(start + 1, Math.min(bins, Math.floor(hi / maxHz * bins)));
408:         let energy = 0;
409:         if (active) {
410:           for (let i = start; i < end; i++) energy += deck.data[i];
411:           energy /= (end - start) * 255;
412:         } else {
413:           const wave = Math.sin((pos * 0.083) + band * 1.7 + (id === 'b' ? 0.8 : 0));
414:           energy = deck.audio.src ? 0.12 + Math.abs(wave) * 0.2 : 0.035;
415:         }
416:         const barHeight = Math.max(2, energy * height * 0.75);
417:         const alpha = active ? 0.42 + Math.min(0.55, energy) : 0.20;
418:         ctx.globalAlpha = alpha;
419:         ctx.fillStyle = colors[band];
420:         const yOffset = band === 0 ? -1 : band === 1 ? 0 : 1;
421:         ctx.fillRect(pos * 3, (height - barHeight) / 2 + yOffset * 5, 2, barHeight);
422:         total += energy;
423:       }
424:       if (active && total > 0.14) {
425:         ctx.globalAlpha = 0.25;
426:         ctx.fillStyle = id === 'a' ? '#54e3dc' : '#ff4e97';
427:         ctx.fillRect(pos * 3, 0, 1, height);
428:       }
429:     }
430:     ctx.globalAlpha = 1;
431:     const progress = deck.audio.duration ? deck.audio.currentTime / deck.audio.duration : 0;
432:     const playX = progress * width;
433:     ctx.fillStyle = id === 'a' ? '#dcfff9' : '#ffe0ed';
434:     ctx.shadowColor = id === 'a' ? '#54e3dc' : '#ff4e97'; ctx.shadowBlur = 7;
435:     ctx.fillRect(playX, 0, 1, height); ctx.shadowBlur = 0;
436:     $(`#time-${id}`).textContent = `${formatTime(deck.audio.currentTime || 0)} / ${formatTime(deck.audio.duration)}`;
437:   }
