439:   function updatePhase() {
440:     if (!decks.a || !decks.b) return;
441:     const a = decks.a, b = decks.b;
442:     const beatsA = a.audio.currentTime * a.bpm / 60;
443:     const beatsB = b.audio.currentTime * b.bpm / 60;
444:     const phaseA = ((beatsA % 1) + 1) % 1;
445:     const phaseB = ((beatsB % 1) + 1) % 1;
446:     let delta = Math.abs(phaseA - phaseB) * 60000 / Math.max(a.bpm, 1);
447:     delta = Math.min(delta, 60000 / Math.max(a.bpm, 1) - delta);
448:     $('#phase-readout').textContent = a.audio.src && b.audio.src ? `FASE ${Math.round(delta)} MS` : 'FASE —';
449:   }
