451:   function measurePhaseDifference(a, b) {
452:     const phaseA = ((a.audio.currentTime * a.bpm / 60) % 1 + 1) % 1;
453:     const phaseB = ((b.audio.currentTime * b.bpm / 60) % 1 + 1) % 1;
454:     const beatFraction = Math.min(Math.abs(phaseA - phaseB), 1 - Math.abs(phaseA - phaseB));
455:     return beatFraction * 60000 / Math.max(1, (a.bpm + b.bpm) / 2);
456:   }
