511:   async function importLibraryFile(file) {
512:     if (!file || file.size > 1024 * 1024) { toast('El archivo JSON supera el límite de 1 MB.'); return; }
513:     try {
514:       const payload = JSON.parse(await file.text());
515:       if (!payload || payload.version !== 1 || !Array.isArray(payload.tracks) || payload.tracks.length > 100) {
516:         throw new Error('Formato o versión no compatible.');
517:       }
518:       const imported = payload.tracks.map(normalizeLibraryTrack);
519:       if (!imported.length || imported.some(track => !track)) throw new Error('Hay pistas inválidas en el archivo.');
520:       for (const track of imported) {
521:         const existing = library.findIndex(item => item.name === track.name && item.source === track.source);
522:         if (existing >= 0) library[existing] = track;
523:         else library.unshift(track);
524:       }
525:       library.splice(100);
526:       persistLibrary();
527:       renderLibrary();
528:       toast(`Se importaron ${imported.length} pistas. Los archivos de audio no están incluidos.`);
529:     } catch (error) {
530:       toast(`No se importó la biblioteca: ${error.message || 'JSON inválido.'}`);
531:     }
