182:   function makeDemoWav(bpm, seed) {
183:     const sampleRate = 22050;
184:     const beat = 60 / bpm;
185:     const beatCount = 16;
186:     const length = Math.ceil(sampleRate * beat * beatCount);
187:     const samples = new Float32Array(length);
188:     let state = seed >>> 0;
189:     const random = () => { state = (state * 1664525 + 1013904223) >>> 0; return state / 4294967296; };
190:     for (let b = 0; b < beatCount; b++) {
191:       const start = Math.floor(b * beat * sampleRate);
192:       const kickLength = Math.floor(sampleRate * 0.24);
193:       for (let i = 0; i < kickLength && start + i < length; i++) {
194:         const t = i / sampleRate;
195:         const env = Math.exp(-t * 17);
196:         const freq = 43 + 75 * Math.exp(-t * 28);
197:         samples[start + i] += Math.sin(2 * Math.PI * freq * t) * env * 0.78;
198:       }
199:       if (b % 4 === 1 || b % 4 === 3) {
200:         const clapStart = start + Math.floor(sampleRate * beat * 0.12);
201:         for (let i = 0; i < sampleRate * 0.15 && clapStart + i < length; i++) {
202:           const t = i / sampleRate;
203:           samples[clapStart + i] += (random() * 2 - 1) * Math.exp(-t * 24) * 0.17;
204:         }
205:       }
206:       const hatStart = start + Math.floor(sampleRate * beat * 0.5);
207:       for (let i = 0; i < sampleRate * 0.045 && hatStart + i < length; i++) {
208:         const t = i / sampleRate;
209:         samples[hatStart + i] += (random() * 2 - 1) * Math.exp(-t * 75) * 0.08;
210:       }
211:     }
212:     const buffer = new ArrayBuffer(44 + samples.length * 2);
213:     const view = new DataView(buffer);
214:     const write = (offset, text) => [...text].forEach((char, index) => view.setUint8(offset + index, char.charCodeAt(0)));
215:     write(0, 'RIFF'); view.setUint32(4, 36 + samples.length * 2, true); write(8, 'WAVE');
216:     write(12, 'fmt '); view.setUint32(16, 16, true); view.setUint16(20, 1, true);
217:     view.setUint16(22, 1, true); view.setUint32(24, sampleRate, true); view.setUint32(28, sampleRate * 2, true);
218:     view.setUint16(32, 2, true); view.setUint16(34, 16, true); write(36, 'data');
219:     view.setUint32(40, samples.length * 2, true);
220:     for (let i = 0; i < samples.length; i++) view.setInt16(44 + i * 2, Math.max(-1, Math.min(1, samples[i])) * 32767, true);
221:     return new Blob([buffer], { type: 'audio/wav' });
222:   }
